ders("BA-05", "BA", "Scrum Guide 2020 ve BABOK v3 · İş İngilizcesi", 5, "İş analizi 5: Çevik çalışma",
 "kıdemli iş analisti dizisi", "Çevik çalışma: Scrum toplantıları ve iş listesi yönetimi.",
 ["bf_emma", "am_michael"], "bf_emma", [
 K("product backlog", "ürün iş listesi.", "The product backlog has over two hundred items.", "Ürün iş listesinde iki yüzden fazla madde var."),
 K("product owner", "ürün sahibi.", "The product owner decides what we build next.", "Bir sonraki adımda ne geliştireceğimize ürün sahibi karar veriyor."),
 K("sprint", "sprint, kısa geliştirme dönemi.", "Our sprints last two weeks.", "Sprintlerimiz iki hafta sürüyor."),
 K("backlog refinement", "iş listesi iyileştirme.", "We clarify user stories during backlog refinement.", "Kullanıcı hikâyelerini iş listesi iyileştirmede netleştiriyoruz."),
 K("sprint goal", "sprint hedefi.", "Every sprint needs a clear sprint goal.", "Her sprintin net bir hedefi olmalı."),
 K("daily stand-up", "günlük kısa toplantı.", "The daily stand-up takes fifteen minutes.", "Günlük kısa toplantı on beş dakika sürüyor."),
 K("definition of done", "bitti tanımı.", "Testing is part of our definition of done.", "Test, bitti tanımımızın bir parçası."),
 K("epic", "büyük iş kalemi, epik.", "We split the epic into smaller user stories.", "Büyük iş kalemini daha küçük kullanıcı hikâyelerine böldük."),
 K("story points", "hikâye puanı.", "The team estimated this story at five story points.", "Ekip bu hikâyeyi beş puan olarak tahmin etti."),
 K("velocity", "ekip hızı.", "Our velocity is about thirty points per sprint.", "Ekip hızımız sprint başına yaklaşık otuz puan."),
 K("retrospective", "geriye dönük değerlendirme toplantısı.", "In the retrospective, we discussed what went wrong.", "Geriye dönük değerlendirmede neyin ters gittiğini konuştuk."),
 K("MVP", "en az uygulanabilir ürün.", "The MVP will include only online applications.", "En az uygulanabilir ürün yalnızca çevrimiçi başvuruları içerecek."),
 ], [P("Is this story ready for the sprint?", "Bu hikâye sprinte hazır mı?"), P("Let's split this into smaller stories.", "Bunu daha küçük hikâyelere bölelim."),
     P("What's blocking you?", "Seni ne engelliyor?"), P("That's out of scope for the MVP.", "Bu, ilk ürünün kapsamı dışında.")],
 "Şimdi bir iş listesi iyileştirme toplantısını dinleyeceksiniz. İş analisti, ürün sahibi ve bir geliştirici konuşuyor.",
 ["PO|For the MVP, customers must be able to apply for a car loan online. That's our sprint goal for the next two sprints.",
  "BA|The epic is quite large. I suggest we split it into smaller user stories: personal details, vehicle details and document upload.",
  "DEV|Good idea. Document upload looks complex. I'd estimate it at eight story points.",
  "PO|Our velocity is around thirty points per sprint, so that fits.",
  "BA|Before we add it to the sprint, is the story ready? Do we have acceptance criteria?",
  "DEV|Not yet. We don't know the maximum file size.",
  "BA|I'll check with the operations team and update the story before the next backlog refinement.",
  "PO|What about electronic signatures?",
  "BA|That's out of scope for the MVP. I'll keep it in the product backlog for later.",
  "DEV|And remember, our definition of done includes security testing.",
  "PO|Agreed. Let's review how this worked in the retrospective."],
 [Q("What is the sprint goal?", "Customers must be able to apply for a car loan online."),
  Q("How many story points did the developer give document upload?", "Eight."),
  Q("What will happen to electronic signatures?", "They stay in the product backlog for later.")],
 [konusma("Toplantı simülasyonu", ["Şimdi bir toplantı simülasyonu. Ürün sahibi sprintin ortasında yeni ve büyük bir istek ekliyor.",
                                   "Sprint hedefini koruyarak kibarca cevap verin. On beş saniyeniz var."],
          "Can we add electronic signatures to this sprint? It's urgent.",
          ["I understand it's important.", "But adding it now would put the sprint goal at risk.",
           "Could we refine it this week and plan it for the next sprint?"], 15),
  konusma("Mülakat köşesi", MULAKAT, "What is the role of a business analyst in a Scrum team?",
          ["A business analyst helps the product owner turn business needs into clear, testable user stories.",
           "I usually lead backlog refinement, split large epics, and write acceptance criteria with the team.",
           "I also talk to stakeholders, so that developers can focus on building.",
           "In short, I make sure that the team builds the right thing, not just builds things right."])],
 konusmacilar={"PO": "af_heart", "BA": "bf_emma", "DEV": "am_michael"},
 dinleme_en=["Scrum is built on short cycles called sprints.", "At the start of each sprint, the team agrees on a sprint goal.",
             "Every day, they meet for a short stand-up to check progress.", "At the end, they show the result to stakeholders in a sprint review.",
             "Then they hold a retrospective to improve the way they work.",
             "The idea is simple: deliver value often, learn quickly and adapt."],
 dinleme_en_sesi="bm_lewis"),

